actions.script:
const out = ec.service.sync().name('org.moqui.chat.ChatStickerServices.get#StickerImage').parameters({chatStickerId: chatStickerId || '',
    thumb: String(thumb) === 'true'}).call() || {}
if (ec.message.hasError() || !out.location) { ec.web.response.setStatus(404); ec.web.sendJsonResponse({}); return }
ec.web.response.setHeader('X-Content-Type-Options', 'nosniff')
ec.web.response.setHeader('Cache-Control', 'private, max-age=86400')
ec.web.sendResourceResponse(out.location, true)

const out = ec.service.sync().name('org.moqui.chat.ChatStickerServices.send#Sticker').parameters({chatRoomId: chatRoomId || '',
    chatStickerId: chatStickerId || '', replyToEventSeq: replyToEventSeq ? Number(replyToEventSeq) : null,
    threadRootEventSeq: threadRootEventSeq ? Number(threadRootEventSeq) : null, clientRef: clientRef || null,
    roomUrl: (ec.factory.getConfValue('comms@app-root') || '/qapps/BasicComms') + '/Chat?chatRoomId=' + encodeURIComponent(chatRoomId || '')}).call() || {}
ec.web.sendJsonResponse(ec.message.hasError() ? {reasonCode: out.reasonCode || null} : {eventSeq: out.eventSeq, event: out.event, clientRef: clientRef || null})

let place = {}
try { place = JSON.parse(locationJson || '{}') } catch (err) { place = {} }
const out = ec.service.sync().name('org.moqui.chat.ChatLocationServices.send#Location').parameters({chatRoomId: chatRoomId || '',
    location: place && typeof place === 'object' ? place : {}, replyToEventSeq: replyToEventSeq ? Number(replyToEventSeq) : null,
    threadRootEventSeq: threadRootEventSeq ? Number(threadRootEventSeq) : null, clientRef: clientRef || null,
    roomUrl: (ec.factory.getConfValue('comms@app-root') || '/qapps/BasicComms') + '/Chat?chatRoomId=' + encodeURIComponent(chatRoomId || '')}).call() || {}
ec.web.sendJsonResponse(ec.message.hasError() ? {reasonCode: out.reasonCode || null} : {eventSeq: out.eventSeq, event: out.event, clientRef: clientRef || null})

const thru = Number(thruDate)
const out = ec.service.sync().name('org.moqui.chat.ChatLocationServices.send#LiveLocation').parameters({chatRoomId: chatRoomId || '',
    thruDate: Number.isFinite(thru) ? new Date(thru) : null, precisionEnumId: precisionEnumId === 'LspApproximate' ? 'LspApproximate' : 'LspExact',
    label: label || null, replyToEventSeq: replyToEventSeq ? Number(replyToEventSeq) : null,
    threadRootEventSeq: threadRootEventSeq ? Number(threadRootEventSeq) : null, clientRef: clientRef || null,
    roomUrl: (ec.factory.getConfValue('comms@app-root') || '/qapps/BasicComms') + '/Chat?chatRoomId=' + encodeURIComponent(chatRoomId || '')}).call() || {}
ec.web.sendJsonResponse(ec.message.hasError() ? {reasonCode: out.reasonCode || null} : {eventSeq: out.eventSeq, event: out.event, shareId: out.shareId,
    thruDate: out.thruDate, intervalSeconds: out.intervalSeconds, duplicate: !!out.duplicate, clientRef: clientRef || null})

const out = ec.service.sync().name('org.moqui.chat.ChatLocationServices.get#LiveLocation').parameters({chatRoomId: chatRoomId || '',
    eventSeq: eventSeq ? Number(eventSeq) : null}).call() || {}
if (ec.message.hasError()) { ec.message.clearErrors(); ec.web.sendJsonResponse({state: null, reasonCode: out.reasonCode || 'notFound'}) }
else ec.web.sendJsonResponse({state: out.state, owner: !!out.owner, share: out.share || null, latest: out.latest || null})

const value = (name) => (context[name] == null ? null : String(context[name]).trim() || null)
const observed = Number(context.observedDate)
let answer = {statusCode: 500, reasonCode: 'FAILED'}
ec.message.pushErrors()
try {
    const out = ec.service.sync().name('org.moqui.maps.LocationServices.report#Position').requireNewTransaction(true)
        .parameters({shareId: String(shareId ?? ''), latitude: value('latitude'), longitude: value('longitude'), accuracy: value('accuracy'),
            heading: value('heading'), speed: value('speed'), audienceVersion: value('audienceVersion'),
            observedDate: value('observedDate') && Number.isFinite(observed) ? new Date(observed) : null}).call() || {}
    answer = {statusCode: Number(out.statusCode) || (ec.message.hasError() ? 400 : 200), reasonCode: out.reasonCode || null,
        retryAfterSeconds: out.retryAfterSeconds == null ? null : Number(out.retryAfterSeconds)}
} catch (err) {
    // the failure's text may hold what was posted: it is not logged or answered
    answer = {statusCode: 500, reasonCode: 'FAILED'}
} finally { ec.message.clearErrors(); ec.message.popErrors() }
if (answer.statusCode === 200) {
    ec.message.pushErrors()
    try {
        const got = ec.service.sync().name('org.moqui.maps.LocationServices.get#Share').parameters({shareId: String(shareId ?? ''), trailPageSize: 1})
            .requireNewTransaction(true).call() || {}
        if (!ec.message.hasError() && got.latest) answer.latest = got.latest
    } finally { ec.message.clearErrors(); ec.message.popErrors() }
}
ec.web.sendJsonResponse(answer)

const out = ec.service.sync().name('org.moqui.maps.LocationServices.update#Share').requireNewTransaction(true)
    .parameters({shareId: String(shareId ?? ''), sendFromHere: true}).call() || {}
if (ec.message.hasError()) { const reason = ec.message.getErrorsString(); ec.message.clearErrors(); ec.web.sendJsonResponse({applied: false, reasonCode: out.reasonCode, reason}) }
else ec.web.sendJsonResponse({applied: true, thruDate: out.thruDate ? ec.user.timestampMillis(out.thruDate) : null})

const out = ec.service.sync().name('org.moqui.maps.LocationServices.stop#Share').requireNewTransaction(true)
    .parameters({shareId: String(shareId ?? '')}).call() || {}
if (ec.message.hasError()) { const reason = ec.message.getErrorsString(); ec.message.clearErrors(); ec.web.sendJsonResponse({applied: false, reasonCode: out.reasonCode, reason}) }
else ec.web.sendJsonResponse({applied: true})
